 const findings=filtered.filter(r=>r.kind==="finding"),open=findings.filter(f=>f.status==="open"),missions=filtered.filter(r=>r.kind==="mission"),memories=filtered.filter(r=>r.kind==="memory"),roadmaps=filtered.filter(r=>r.kind==="roadmap");
 const refresh=useCallback(async(silent=false)=>{if(!silent)setLoading(true);try{let r=await fetch("/api/workspace");let d:any=await r.json();if(!r.ok)throw new Error(d.error);if(!d.records.some((x:any)=>x.kind==="swarm")){r=await fetch("/api/workspace",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"initialize"})});d=await r.json();if(!r.ok)throw new Error(d.error)}setRecords(d.records);setError("")}catch(e:any){setError(e.message)}finally{setLoading(false)}},[]);
 useEffect(()=>{refresh()},[refresh]);
 useEffect(()=>{if(new URLSearchParams(location.search).has("github"))setPage("runtime");const initial=location.hash.slice(1);if(nav.some(n=>n.id===initial))setPage(initial);const change=()=>{const h=location.hash.slice(1);if(nav.some(n=>n.id===h))setPage(h)};addEventListener("hashchange",change);return()=>removeEventListener("hashchange",change)},[]);
 const navigate=(p:string)=>{setPage(p);setSearch("");history.replaceState(null,"","#"+p)};
 const act=useCallback(async(payload:any,message="Saved")=>{setBusy(true);try{const r=await fetch("/api/workspace",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const d:any=await r.json();if(!r.ok)throw new Error(d.error);setRecords(d.records);setError("");toast.success(message);return d;}catch(e:any){toast.error(e.message);throw e}finally{setBusy(false)}},[]);
 const perform=(p:any,msg?:string)=>{act(p,msg).catch(()=>{})};
 const openModal=(name:string)=>{setTitle("");setContent("");setEndpoint("");setImportFiles([]);setFileError("");setParentId(swarms.find(s=>!s.data.parentId)?.id||"");setModal(name)};
 useEffect(()=>{const ctx=(document as any).modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();for(const tool of [{name:"read_omnidev_workspace",description:"Read the current workspace projects, swarms, and findings",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({projects:records.filter(r=>r.kind==="project").map(r=>({id:r.id,title:r.title,source:r.data.source})),swarms:records.filter(r=>r.kind==="swarm").length,findings:records.filter(r=>r.kind==="finding")})},{name:"create_omnidev_memory",description:"Save a free-text decision note in global memory. Structured decisions with outcomes are recorded in Evidence & recovery.",inputSchema:{type:"object",properties:{title:{type:"string"},content:{type:"string"}},required:["title","content"],additionalProperties:false},annotations:{readOnlyHint:false},execute:async(i:any)=>{if(typeof i.title!=="string"||typeof i.content!=="string"||!i.title.trim()||!i.content.trim())throw new Error("Title and content are required");const d=await act({action:"memory",type:"Decision",title:i.title,content:i.content});return {id:d.id,status:"saved"}}}]){try{Promise.resolve(ctx.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}return()=>lifecycle.abort()},[records,act]);
 async function readFiles(input:FileList|null){if(!input)return;setFileError("");try{const selected=Array.from(input);if(selected.length>300||selected.reduce((a,f)=>a+f.size,0)>2000000)throw new Error("Select up to 300 text files, under 2 MB total.");const files:any[]=[];for(const f of selected){if(f.size>100000)throw new Error(f.name+" exceeds 100 KB.");const c=await f.text();if(c.includes("\u0000"))throw new Error("Binary files are unsupported: "+f.name);files.push({path:(f as any).webkitRelativePath||f.name,content:c})}setImportFiles(files);if(!title&&selected[0])setTitle((selected[0] as any).webkitRelativePath?.split("/")[0]||"Imported project")}catch(e:any){setFileError(e.message)}}
 const projectOptions=[{id:"all",label:"All projects"},...projects.map(p=>({id:p.id,label:p.title})),{id:"__new_project__",label:"＋ New project"}];
 const primary=()=>openModal("mission");
 const newExample=()=>{act({action:"example"},"Example snapshot analyzed").then(d=>{setProjectId(d.projectId)}).catch(()=>{})};
 const recommendations=projectRecommendations(filtered,projectId==="all"?undefined:projectId);
 const priorityFindings=rankCurrentFindings(filtered,projectId==="all"?undefined:projectId);
 const viewFindings=scopeFindings(filtered,projectId,page==="security"?"Security":undefined);
 const findingStats=findingSummary(viewFindings);
 const showFinding=(f:RecordItem)=>setDetail({type:"finding",...f,recommendation:recommendations.find(r=>r.id===f.id)});
 const scopedAction=async(payload:any,message:string)=>{try{const source=project?await planningSource(project,records):undefined;await act({...payload,projectId:project?.id||"",...(source?{expectedSourceDigest:source.sourceDigest}:{})},message)}catch(e:any){toast.error(e.message||"Could not save the change")}};
 const scoreEntries=analysis?Object.entries(analysis.scores):[];
